import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[] pivotArray(int[] nums, int pivot) {
        List<Integer> less = new ArrayList<>();
        List<Integer> equal = new ArrayList<>();
        List<Integer> greater = new ArrayList<>();
        for (int value : nums) {
            if (value < pivot) {
                less.add(value);
            } else if (value == pivot) {
                equal.add(value);
            } else {
                greater.add(value);
            }
        }
        int[] result = new int[nums.length];
        int index = 0;
        for (int value : less) {
            result[index++] = value;
        }
        for (int value : equal) {
            result[index++] = value;
        }
        for (int value : greater) {
            result[index++] = value;
        }
        return result;
    }
}

class Solution {
    public int[] pivotArray(int[] nums, int pivot) {
        int lessCount = 0;
        int equalCount = 0;
        for (int value : nums) {
            if (value < pivot) {
                lessCount++;
            } else if (value == pivot) {
                equalCount++;
            }
        }
        int lessIndex = 0;
        int equalIndex = lessCount;
        int greaterIndex = lessCount + equalCount;
        int[] result = new int[nums.length];
        for (int value : nums) {
            if (value < pivot) {
                result[lessIndex++] = value;
            } else if (value == pivot) {
                result[equalIndex++] = value;
            } else {
                result[greaterIndex++] = value;
            }
        }
        return result;
    }
}

class Solution {
    public int[] pivotArray(int[] nums, int pivot) {
        int n = nums.length;
        int[] result = new int[n];
        int left = 0;
        int right = n - 1;
        for (int i = 0, j = n - 1; i < n; i++, j--) {
            if (nums[i] < pivot) {
                result[left++] = nums[i];
            }
            if (nums[j] > pivot) {
                result[right--] = nums[j];
            }
        }
        while (left <= right) {
            result[left++] = pivot;
        }
        return result;
    }
}

import java.util.Arrays;

class Solution {
    public int[] pivotArray(int[] nums, int pivot) {
        Integer[] order = new Integer[nums.length];
        for (int i = 0; i < nums.length; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> {
            int categoryA = category(nums[a], pivot);
            int categoryB = category(nums[b], pivot);
            if (categoryA != categoryB) {
                return categoryA - categoryB;
            }
            return a - b;
        });
        int[] result = new int[nums.length];
        for (int i = 0; i < order.length; i++) {
            result[i] = nums[order[i]];
        }
        return result;
    }

    private int category(int value, int pivot) {
        if (value < pivot) {
            return 0;
        }
        if (value == pivot) {
            return 1;
        }
        return 2;
    }
}
